const input = $input.first().json || {};
const headers = input.headers || {};
const body = input.body || input;
const secret = String($env.N8N_WEBHOOK_SECRET || '').trim();
const incoming = String(headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || headers['x-mdoctor-webhook-secret'] || headers['X-MDoctor-Webhook-Secret'] || '').trim();
if (secret && incoming !== secret) throw new Error('Invalid webhook secret');

const flowEnv = String($env.FLOW_ENV || 'staging').toLowerCase();
if (flowEnv !== 'staging') throw new Error('FLOW_ENV must be staging');

const phone = String(body.phone || body.paciente_telefone || body.to || '').replace(/\D/g, '');
if (!phone) throw new Error('phone required');

const message = String(body.message || 'Após avaliação médica, não foi possível aprovar sua renovação de receita por teleconsulta. Recomendamos atendimento presencial para melhor avaliação.');
const dryRun = body.dryRun === true || String($env.WHATSAPP_DRY_RUN || 'true') === 'true';
const atendimentoId = String(body.atendimentoId || body.atendimento_id || '').trim();
const correlationId = String(body.correlationId || headers['x-correlation-id'] || headers['X-Correlation-Id'] || `reject-${Date.now()}`);
const idempotencyKey = String(
  headers['idempotency-key'] ||
  headers['Idempotency-Key'] ||
  body.idempotency_key ||
  (atendimentoId ? `clinical-reject:${atendimentoId}` : `clinical-reject:${phone}:${correlationId}`)
);

const backendUrl = String(
  $env.BACKEND_BASE_URL || $env.BACKEND_URL_STAGING || 'https://mdoctor-backend-staging-staging.up.railway.app'
).replace(/\/$/, '');
if (backendUrl.includes('web-production')) throw new Error('Backend staging must not be production web');

return [{
  json: {
    phone,
    message,
    dryRun,
    backendUrl,
    atendimentoId: atendimentoId || null,
    correlationId,
    idempotencyKey,
    secret
  }
}];
